package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

public class JsonWriter_value_TriageGen2Test {

    private StringWriter out;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        out = new StringWriter();
        jsonWriter = new JsonWriter(out);
    }

    @Test
    public void testValueLong_Positive() throws IOException {
        jsonWriter.beginObject();
        jsonWriter.name("id");
        JsonWriter result = jsonWriter.value(123456789L);
        jsonWriter.endObject();

        assertEquals("{\"id\":123456789}", out.toString());
        assertSame(jsonWriter, result);
    }

    @Test
    public void testValueLong_Zero() throws IOException {
        jsonWriter.beginArray();
        jsonWriter.value(0L);
        jsonWriter.endArray();

        assertEquals("[0]", out.toString());
    }

    @Test
    public void testValueLong_Negative() throws IOException {
        jsonWriter.beginObject();
        jsonWriter.name("offset");
        jsonWriter.value(-987654321L);
        jsonWriter.endObject();

        assertEquals("{\"offset\":-987654321}", out.toString());
    }

    @Test
    public void testValueLong_LongMaxValue() throws IOException {
        jsonWriter.beginArray();
        jsonWriter.value(Long.MAX_VALUE);
        jsonWriter.endArray();

        assertEquals("[" + Long.MAX_VALUE + "]", out.toString());
    }

    @Test
    public void testValueLong_LongMinValue() throws IOException {
        jsonWriter.beginArray();
        jsonWriter.value(Long.MIN_VALUE);
        jsonWriter.endArray();

        assertEquals("[" + Long.MIN_VALUE + "]", out.toString());
    }

    @Test
    public void testValueLong_ChainedCalls() throws IOException {
        // Testing that the return type allows chaining and integrates with other types
        jsonWriter.beginObject()
                .name("a")
                .value(1L)
                .name("b")
                .value(2L)
                .endObject();

        assertEquals("{\"a\":1,\"b\":2}", out.toString());
    }

    @Test
    public void testValueLong_AfterName() throws IOException {
        // Specifically targeting the writeDeferredName() logic via name()
        jsonWriter.beginObject();
        jsonWriter.name("key");
        jsonWriter.value(100L);
        jsonWriter.endObject();

        assertEquals("{\"key\":100}", out.toString());
    }
}
